pm.test("every product has id, name, price, brand and category", () => {
    body.products.forEach(product => {
        pm.expect(product).to.have.all.keys("id", "name", "price", "brand", "category");
    });
});

pm.test("every result has 'top' in its name or category", () => {
    body.products.forEach(product => {
        const name = product.name.toLowerCase();
        const category = product.category.category.toLowerCase();
        pm.expect(name.includes("top") || category.includes("top"),
            `${product.name} does not relate to 'top'`).to.be.true;
    });
});

